38	/// Check if an error chain indicates the worker should be reported as down.
39	fn is_inhibited(err: &(dyn std::error::Error + 'static)) -> bool {
40	    const INHIBITED: &[ErrorType] = &[
41	        ErrorType::CannotConnect,
42	        ErrorType::Disconnected,
43	        ErrorType::ConnectionTimeout,
44	        ErrorType::ResponseTimeout,
45	        ErrorType::Backend(BackendError::EngineShutdown),
46	        // A stream that ends mid-generation means this worker dropped the
47	        // request. Quarantine it, or a migration retry can reselect the same
48	        // worker before discovery removal catches up.
49	        ErrorType::Backend(BackendError::StreamIncomplete),
50	    ];
51	    match_error_chain(err, INHIBITED, &[])
52	}
