54	/// Read the backend response inactivity timeout from the environment.
55	/// Reuses `DYN_HTTP_BACKEND_STREAM_TIMEOUT_SECS` — the same env var
56	/// as the HTTP-layer safety net in `disconnect.rs`.
57	fn response_inactivity_timeout() -> Option<std::time::Duration> {
58	    use crate::config::environment_names::llm::DYN_HTTP_BACKEND_STREAM_TIMEOUT_SECS;
59	    std::env::var(DYN_HTTP_BACKEND_STREAM_TIMEOUT_SECS)
60	        .ok()
61	        .and_then(|s| s.parse::<u64>().ok())
62	        .filter(|&secs| secs > 0)
63	        .map(std::time::Duration::from_secs)
64	}
