66	/// RAII handle for one in-flight unit of work charged against
67	/// [`RoutingOccupancyState`]. The counter is incremented at construction; the
68	/// matching decrement is emitted on drop (or by [`Self::into_tracked_stream`]).
69	struct OccupancyPermit {
70	    reservation: Option<OccupancyReservation>,
71	}
72	
73	impl OccupancyPermit {
74	    fn acquire(state: Arc<RoutingOccupancyState>, instance_id: u64) -> Self {
75	        Self {
76	            reservation: Some(state.reserve(instance_id)),
77	        }
78	    }
79	
80	    fn from_counter(
81	        state: Arc<RoutingOccupancyState>,
82	        instance_id: u64,
83	        counter: Arc<AtomicU64>,
84	    ) -> Self {
85	        Self {
86	            reservation: Some(OccupancyReservation::from_counter(
87	                state,
88	                instance_id,
89	                counter,
90	            )),
91	        }
92	    }
93	
94	    fn retarget(&mut self, instance_id: u64) {
95	        self.reservation
96	            .as_mut()
97	            .expect("occupancy permit must be armed before stream tracking")
98	            .retarget(instance_id);
99	    }
100	
101	    fn into_tracked_stream<U: Data + MaybeError>(mut self, stream: ManyOut<U>) -> ManyOut<U> {
102	        let engine_ctx = stream.context();
103	        ResponseStream::new(
104	            Box::pin(OccupancyTrackedStream {
105	                inner: stream,
106	                reservation: self.reservation.take(),
107	            }),
108	            engine_ctx,
109	        )
110	    }
111	}
