304	fn route_pickers(
305	    router_mode: RouterMode,
306	) -> (Arc<RoutePicker>, Arc<RoutePicker>, Option<Arc<RoutePicker>>) {
307	    let round_robin = Arc::new(RoutePicker::new(RoutePolicy::RoundRobin));
308	    let random = Arc::new(RoutePicker::new(RoutePolicy::Random));
309	    let configured = match router_mode {
310	        RouterMode::RoundRobin => Some(round_robin.clone()),
311	        RouterMode::Random => Some(random.clone()),
312	        mode => mode.route_policy().map(RoutePicker::new).map(Arc::new),
313	    };
314	    (round_robin, random, configured)
315	}
