357	/// Watch discovery for instance removals and cancel pending response-stream
358	/// registrations on the removed instance, unblocking queued requests with
359	/// a migratable `Disconnected` error. Uses raw `list_and_watch` events
360	/// (not a coalesced snapshot diff) so a rapid remove→re-add of the same
361	/// identity is not silently swallowed. Keyed by full `EndpointInstanceId`.
362	fn spawn_instance_removal_watcher<T, U>(
363	    endpoint: Endpoint,
364	    dispatch: Arc<dyn StreamingDispatch<T, U>>,
365	    cancel_token: tokio_util::sync::CancellationToken,
366	) where
367	    T: Data + Serialize + 'static,
368	    U: Data + for<'de> Deserialize<'de> + MaybeError + 'static,
369	{
370	    use crate::discovery::{
371	        DiscoveryEvent, DiscoveryInstance, DiscoveryInstanceId, DiscoveryQuery,
372	    };
373	    use tokio_stream::StreamExt as _;
374	
375	    // One watcher per endpoint: if one is already running, skip.
376	    let guard = ENDPOINT_WATCHER_ACTIVE.get_or_init(dashmap::DashMap::new);
377	    let endpoint_id = endpoint.id();
378	    if guard.insert(endpoint_id.clone(), ()).is_some() {
379	        tracing::debug!(
380	            ?endpoint_id,
381	            "Instance removal watcher already running for this endpoint, skipping"
382	        );
383	        return;
384	    }
385	
386	    let endpoint_name = endpoint.name().to_string();
387	
388	    tokio::spawn(async move {
389	        // Release on every exit path (including panic); a leaked entry
390	        // silently disables removal cancellation until process restart.
391	        struct GuardRelease(EndpointId);
392	        impl Drop for GuardRelease {
393	            fn drop(&mut self) {
394	                if let Some(map) = ENDPOINT_WATCHER_ACTIVE.get() {
395	                    map.remove(&self.0);
396	                }
397	            }
398	        }
399	        let _release = GuardRelease(endpoint_id);
400	
401	        let namespace = endpoint.component().namespace().name();
402	        let component = endpoint.component().name().to_string();
403	
404	        // Reconnect on transient discovery failure; cancel-aware backoff.
405	        const RECONNECT_BACKOFF: std::time::Duration = std::time::Duration::from_secs(5);
406	        'reconnect: loop {
407	            let query = DiscoveryQuery::Endpoint {
408	                namespace: namespace.clone(),
409	                component: component.clone(),
410	                endpoint: endpoint_name.clone(),
411	            };
412	
413	            let mut stream = match endpoint.drt().discovery().list_and_watch(query, None).await {
414	                Ok(s) => s,
415	                Err(e) => {
416	                    tracing::warn!(
417	                        endpoint = %endpoint_name,
418	                        "Failed to start instance removal watcher (will retry): {e}"
419	                    );
420	                    tokio::select! {
421	                        _ = tokio::time::sleep(RECONNECT_BACKOFF) => continue 'reconnect,
422	                        _ = cancel_token.cancelled() => break 'reconnect,
423	                    }
424	                }
425	            };
426	
427	            loop {
428	                tokio::select! {
429	                    event = stream.next() => {
430	                        match event {
431	                            Some(Ok(DiscoveryEvent::Removed(id))) => {
432	                                if let DiscoveryInstanceId::Endpoint(eid) = &id {
433	                                    dispatch.on_instance_removed(eid).await;
434	                                }
435	                            }
436	                            Some(Ok(DiscoveryEvent::Added(DiscoveryInstance::Endpoint(inst)))) => {
437	                                let eid: EndpointInstanceId = inst.endpoint_instance_id();
438	                                dispatch.on_instance_added(&eid).await;
439	                            }
440	                            Some(Ok(_)) => {}
441	                            Some(Err(e)) => {
442	                                tracing::warn!(
443	                                    endpoint = %endpoint_name,
444	                                    "Instance removal watcher stream error: {e}"
445	                                );
446	                            }
447	                            None => {
448	                                tracing::warn!(
449	                                    endpoint = %endpoint_name,
450	                                    "Instance removal watcher stream ended; reconnecting"
451	                                );
452	                                continue 'reconnect;
453	                            }
454	                        }
455	                    }
456	                    _ = cancel_token.cancelled() => {
457	                        break 'reconnect;
458	                    }
459	                }
460	            }
461	        }
462	
463	        tracing::debug!(endpoint = %endpoint_name, "Instance removal watcher exiting");
464	    });
465	}
