467	/// Watch discovery removals for cache-aware routers and drop stale worker cache entries.
468	fn spawn_multimodal_cache_cleanup_watcher(
469	    endpoint: Endpoint,
470	    indexer: Arc<dyn MultimodalCacheIndex>,
471	    cancel_token: tokio_util::sync::CancellationToken,
472	) {
473	    use crate::discovery::{DiscoveryEvent, DiscoveryInstanceId, DiscoveryQuery};
474	    use tokio_stream::StreamExt as _;
475	
476	    let guard = ENDPOINT_CACHE_INDEXER_WATCHER_ACTIVE.get_or_init(dashmap::DashMap::new);
477	    let watcher_id = RuntimeEndpointId::for_endpoint(&endpoint);
478	    if guard.insert(watcher_id.clone(), ()).is_some() {
479	        tracing::debug!(
480	            connection_id = watcher_id.connection_id,
481	            ?watcher_id.endpoint_id,
482	            "Multimodal cache cleanup watcher already running for this runtime endpoint, skipping"
483	        );
484	        return;
485	    }
486	
487	    let endpoint_name = endpoint.name().to_string();
488	    let namespace = endpoint.component().namespace().name();
489	    let component = endpoint.component().name().to_string();
490	
491	    tokio::spawn(async move {
492	        struct GuardRelease(RuntimeEndpointId);
493	        impl Drop for GuardRelease {
494	            fn drop(&mut self) {
495	                if let Some(map) = ENDPOINT_CACHE_INDEXER_WATCHER_ACTIVE.get() {
496	                    map.remove(&self.0);
497	                }
498	            }
499	        }
500	        let _release = GuardRelease(watcher_id);
501	
502	        const RECONNECT_BACKOFF: std::time::Duration = std::time::Duration::from_secs(5);
503	        'reconnect: loop {
504	            let query = DiscoveryQuery::Endpoint {
505	                namespace: namespace.clone(),
506	                component: component.clone(),
507	                endpoint: endpoint_name.clone(),
508	            };
509	
510	            let mut stream = match endpoint.drt().discovery().list_and_watch(query, None).await {
511	                Ok(stream) => stream,
512	                Err(error) => {
513	                    tracing::warn!(
514	                        endpoint = %endpoint_name,
515	                        "Failed to start multimodal cache cleanup watcher (will retry): {error}"
516	                    );
517	                    tokio::select! {
518	                        _ = tokio::time::sleep(RECONNECT_BACKOFF) => continue 'reconnect,
519	                        _ = cancel_token.cancelled() => break 'reconnect,
520	                    }
521	                }
522	            };
523	
524	            loop {
525	                tokio::select! {
526	                    event = stream.next() => {
527	                        match event {
528	                            Some(Ok(DiscoveryEvent::Removed(DiscoveryInstanceId::Endpoint(eid)))) => {
529	                                indexer.remove_worker(eid.instance_id);
530	                            }
531	                            Some(Ok(_)) => {}
532	                            Some(Err(error)) => {
533	                                tracing::warn!(
534	                                    endpoint = %endpoint_name,
535	                                    "Multimodal cache cleanup watcher stream error: {error}"
536	                                );
537	                                continue 'reconnect;
538	                            }
539	                            None => {
540	                                tracing::warn!(
541	                                    endpoint = %endpoint_name,
542	                                    "Multimodal cache cleanup watcher stream ended; reconnecting"
543	                                );
544	                                continue 'reconnect;
545	                            }
546	                        }
547	                    }
548	                    _ = cancel_token.cancelled() => break 'reconnect,
549	                }
550	            }
551	        }
552	
553	        tracing::debug!(endpoint = %endpoint_name, "Multimodal cache cleanup watcher exiting");
554	    });
555	}
