561	impl<T, U> PushRouter<T, U>
562	where
563	    T: Data + Serialize,
564	    U: Data + for<'de> Deserialize<'de> + MaybeError,
565	{
566	    pub fn router_mode(&self) -> RouterMode {
567	        self.router_mode
568	    }
569	
570	    /// Create a new PushRouter without a worker load monitor (no overload detection)
571	    pub async fn from_client(client: Client, router_mode: RouterMode) -> anyhow::Result<Self> {
572	        Self::from_client_with_monitor(client, router_mode, None).await
573	    }
574	
575	    /// Create a new PushRouter with fault detection disabled.
576	    ///
577	    /// Unlike `from_client`, this router will not call `report_instance_down` on
578	    /// transient errors, and `direct()` uses the raw discovery instance list instead
579	    /// of the filtered avail list. Use for recovery/query paths.
580	    pub async fn from_client_no_fault_detection(
581	        client: Client,
582	        router_mode: RouterMode,
583	    ) -> anyhow::Result<Self> {
584	        let addressed = addressed_router(&client.endpoint).await?;
585	
586	        let occupancy_state = if router_mode.requires_occupancy() {
587	            Some(get_or_create_routing_occupancy_state(&client.endpoint).await)
588	        } else {
589	            None
590	        };
591	
592	        // Type-erase to the seam so discovery-removal cleanup runs through it.
593	        let addressed: Arc<dyn StreamingDispatch<T, U>> = addressed;
594	        spawn_instance_removal_watcher(
595	            client.endpoint.clone(),
596	            addressed.clone(),
597	            client.endpoint.drt().primary_token(),
598	        );
599	        let (round_robin_picker, random_picker, picker) = route_pickers(router_mode);
600	
601	        Ok(PushRouter {
602	            client,
603	            addressed,
604	            router_mode,
605	            picker,
606	            round_robin_picker,
607	            random_picker,
608	            fault_detection_enabled: false,
609	            response_timeout: response_inactivity_timeout(),
610	            occupancy_state,
611	            multimodal_cache_indexer: None,
612	            multimodal_cache_key_extractor: None,
613	            _phantom: PhantomData,
614	        })
615	    }
616	
617	    /// Create a new PushRouter with an optional worker load monitor.
618	    ///
619	    /// The rejection path is gated by `fault_detection_enabled` (true here);
620	    /// overload detection itself is driven by the monitor via `client.set_overloaded_instances(...)`.
621	    /// If no thresholds are configured on the monitor (or no monitor is provided),
