631	    /// Create a new PushRouter with optional load monitoring and multimodal cache indexing.
632	    pub async fn from_client_with_state(
633	        client: Client,
634	        router_mode: RouterMode,
635	        worker_monitor: Option<Arc<dyn WorkerLoadMonitor>>,
636	        multimodal_cache_indexer: Option<Arc<dyn MultimodalCacheIndex>>,
637	        multimodal_cache_key_extractor: Option<MultimodalCacheKeyExtractor<T>>,
638	    ) -> anyhow::Result<Self> {
639	        let addressed = addressed_router(&client.endpoint).await?;
640	
641	        // Start worker monitor if provided and in dynamic mode
642	        if let Some(monitor) = worker_monitor.as_ref() {
643	            monitor.start_monitoring().await?;
644	        }
645	
646	        let occupancy_state = if router_mode.requires_occupancy() {
647	            Some(get_or_create_routing_occupancy_state(&client.endpoint).await)
648	        } else {
649	            None
650	        };
651	
652	        // Type-erase to the seam so discovery-removal cleanup runs through it.
653	        let addressed: Arc<dyn StreamingDispatch<T, U>> = addressed;
654	        spawn_instance_removal_watcher(
655	            client.endpoint.clone(),
656	            addressed.clone(),
657	            client.endpoint.drt().primary_token(),
658	        );
659	
660	        // Drop stale cache-index entries when workers leave discovery.
661	        if let Some(indexer) = multimodal_cache_indexer.clone() {
662	            spawn_multimodal_cache_cleanup_watcher(
663	                client.endpoint.clone(),
664	                indexer,
665	                client.endpoint.drt().primary_token(),
666	            );
667	        }
668	        let (round_robin_picker, random_picker, picker) = route_pickers(router_mode);
669	
670	        let router = PushRouter {
671	            client,
672	            addressed,
673	            router_mode,
674	            picker,
675	            round_robin_picker,
676	            random_picker,
677	            fault_detection_enabled: true,
678	            response_timeout: response_inactivity_timeout(),
679	            occupancy_state,
680	            multimodal_cache_indexer,
681	            multimodal_cache_key_extractor,
682	            _phantom: PhantomData,
683	        };
684	
685	        Ok(router)
686	    }
