729	    /// `ResourceExhausted` when workers are routable but all overloaded;
730	    /// `Unavailable` when no routable workers exist.
731	    fn empty_free_pool_error(&self, routing_instances: &RoutingInstances) -> anyhow::Error {
732	        if !routing_instances.routable_ids().is_empty() {
733	            let cause = PipelineError::ServiceOverloaded(
734	                "All workers are busy, please retry later".to_string(),
735	            );
736	            return DynamoError::builder()
737	                .error_type(ErrorType::ResourceExhausted)
738	                .message("All workers are busy, please retry later")
739	                .cause(cause)
740	                .build()
741	                .into();
742	        }
743	        DynamoError::builder()
744	            .error_type(ErrorType::Unavailable)
745	            .message(format!(
746	                "No workers available for endpoint {}",
747	                self.client.endpoint.id()
748	            ))
749	            .build()
750	            .into()
751	    }
