762	    fn select_untracked_worker(&self, picker: &RoutePicker) -> anyhow::Result<(u64, usize)> {
763	        let routing_instances = self.client.routing_instances();
764	        let candidates = routing_instances.free_ids();
765	        let decision = picker
766	            .select(
767	                CandidateView::Workers(candidates),
768	                RouteContext::default(),
769	                |_| 0,
770	            )
771	            .ok_or_else(|| self.empty_free_pool_error(&routing_instances))?;
772	        Ok((decision.target.worker_id, candidates.len()))
773	    }
