800	    /// Select a DeviceAware worker while leaving request-lifecycle cleanup to
801	    /// the routing host. Request and device metadata is prepared before the
802	    /// occupancy admission lock is acquired.
803	    pub fn select_device_aware_and_reserve(
804	        &self,
805	        request: &T,
806	        pinned_worker: Option<u64>,
807	    ) -> anyhow::Result<DeviceAwareSelection> {
808	        anyhow::ensure!(
809	            self.router_mode == RouterMode::DeviceAwareWeighted,
810	            "{:?} routing is not DeviceAwareWeighted",
811	            self.router_mode
812	        );
813	
814	        let state = self.occupancy_state()?;
815	        if let Some(worker_id) = pinned_worker {
816	            self.ensure_routable(worker_id)?;
817	            let selection = self.device_aware_candidates(request, &[worker_id]);
818	            let is_cpu = selection
819	                .candidates
820	                .first()
821	                .is_some_and(|candidate| candidate.device == RouteDevice::Cpu);
822	            let reservation = state.reserve(worker_id);
823	            let load = reservation.load();
824	            return Ok(DeviceAwareSelection {
825	                worker_id,
826	                candidate_count: 1,
827	                load,
828	                is_cpu,
829	                embedding_cache_hit: selection.embedding_cache_hit,
830	                request_cache_keys: selection.request_cache_keys,
831	                reservation: Some(reservation),
832	            });
833	        }
834	
835	        let routing_instances = self.client.routing_instances();
836	        let instance_ids = routing_instances.free_ids();
837	        if instance_ids.is_empty() {
838	            return Err(self.empty_free_pool_error(&routing_instances));
839	        }
840	        let selection = self.device_aware_candidates(request, instance_ids);
841	        let (decision, counter) = state
842	            .select_and_admit(
843	                self.picker()?,
844	                CandidateView::DeviceAware(&selection.candidates),
845	                selection.context,
846	            )
847	            .ok_or_else(|| self.empty_free_pool_error(&routing_instances))?;
848	        let worker_id = decision.target.worker_id;
849	        let is_cpu = selection.candidates.iter().any(|candidate| {
850	            candidate.target.worker_id == worker_id && candidate.device == RouteDevice::Cpu
851	        });
852	        let reservation = counter
853	            .map(|counter| OccupancyReservation::from_counter(state.clone(), worker_id, counter));
854	
855	        Ok(DeviceAwareSelection {
856	            worker_id,
857	            candidate_count: selection.candidates.len(),
858	            load: state.load(worker_id),
859	            is_cpu,
860	            embedding_cache_hit: selection.embedding_cache_hit,
861	            request_cache_keys: selection.request_cache_keys,
862	            reservation,
863	        })
864	    }
