1071	    async fn direct_prepared_with_fallback<M, F>(
1072	        &self,
1073	        instance_id: u64,
1074	        request: SingleIn<T>,
1075	        fallback: TransportFallback<'_>,
1076	        prepare: F,
1077	    ) -> anyhow::Result<(M, ManyOut<U>)>
1078	    where
1079	        F: FnOnce(&mut T, u64) -> anyhow::Result<M>,
1080	    {
1081	        // Fallback resolution owns the unavailable-target decision. Allowing it
1082	        // to see a worker already absent from discovery preserves Direct's
1083	        // historical standalone fallback; `Deny` remains exact-target behavior.
1084	        let selected_is_discovered = self
1085	            .client
1086	            .instances()
1087	            .iter()
1088	            .any(|instance| instance.instance_id == instance_id);
1089	        if !selected_is_discovered {
1090	            let fallback_is_available = self
1091	                .client
1092	                .routing_instances()
1093	                .free_ids()
1094	                .iter()
1095	                .copied()
1096	                .any(|candidate| {
1097	                    candidate != instance_id
1098	                        && match fallback {
1099	                            TransportFallback::Allow => true,
1100	                            TransportFallback::Deny => false,
1101	                            TransportFallback::Within(allowed) => allowed.contains(&candidate),
1102	                        }
1103	                });
1104	            if !fallback_is_available {
1105	                self.ensure_discovered_for_dispatch(instance_id)?;
1106	            }
1107	        }
1108	        let ((metadata, resolved_instance_id), response_stream) = self
1109	            .generate_with_fault_detection_prepared(
1110	                instance_id,
1111	                request,
1112	                fallback,
1113	                |request, resolved_instance_id| {
1114	                    prepare(request, resolved_instance_id)
1115	                        .map(|metadata| (metadata, resolved_instance_id))
1116	                },
1117	            )
1118	            .await?;
1119	        tracing::info!(
1120	            router_mode = self.router_mode.telemetry_label(),
1121	            worker_id = resolved_instance_id,
1122	            "Selected worker"
1123	        );
1124	        Ok((metadata, response_stream))
1125	    }
