1127	    async fn dispatch_preselected_with_fallback<M, F>(
1128	        &self,
1129	        instance_id: u64,
1130	        request: SingleIn<T>,
1131	        fallback: TransportFallback<'_>,
1132	        prepare: F,
1133	    ) -> anyhow::Result<(M, ManyOut<U>)>
1134	    where
1135	        F: FnOnce(&mut T, u64) -> anyhow::Result<M>,
1136	    {
