1138	        // discovery. Local inhibition only filters worker selection owned by this router;
1139	        // fallback is considered only if the selected worker disappears after this check.
1140	        self.ensure_discovered_for_dispatch(instance_id)?;
1141	
1142	        self.generate_with_fault_detection_prepared(instance_id, request, fallback, prepare)
1143	            .await
1144	    }
