1215	        match self.router_mode {
1216	            RouterMode::Random => self.random_prepared(request, prepare).await,
1217	            RouterMode::RoundRobin => self.round_robin_prepared(request, prepare).await,
1218	            RouterMode::PowerOfTwoChoices => {
1219	                self.power_of_two_choices_prepared(request, prepare).await
1220	            }
1221	            RouterMode::LeastLoaded => self.least_loaded_prepared(request, prepare).await,
1222	            RouterMode::DeviceAwareWeighted => {
1223	                self.device_aware_weighted_prepared(request, prepare).await
1224	            }
1225	            RouterMode::KV => anyhow::bail!("KV routing should not call select_and_dispatch"),
1226	            RouterMode::Direct => anyhow::bail!(
1227	                "Direct routing should use direct_within_prepared instead of select_and_dispatch"
1228	            ),
1229	        }
1230	    }
