1232	    async fn dispatch_selected<M, F>(
1233	        &self,
1234	        instance_id: u64,
1235	        request: SingleIn<T>,
1236	        mut permit: Option<OccupancyPermit>,
1237	        prepare: F,
1238	    ) -> anyhow::Result<(M, ManyOut<U>)>
1239	    where
1240	        F: FnOnce(&mut T, u64) -> anyhow::Result<M>,
1241	    {
1242	        let (metadata, stream) = self
1243	            .generate_with_fault_detection_prepared(
1244	                instance_id,
1245	                request,
1246	                TransportFallback::Allow,
1247	                |request, resolved_instance_id| {
1248	                    if let Some(permit) = permit.as_mut() {
1249	                        permit.retarget(resolved_instance_id);
1250	                    }
1251	                    prepare(request, resolved_instance_id)
1252	                },
1253	            )
1254	            .await?;
1255	        let stream = match permit {
1256	            Some(permit) => permit.into_tracked_stream(stream),
1257	            None => stream,
1258	        };
1259	        Ok((metadata, stream))
1260	    }
