1262	    /// Issue a request using device-aware weighted routing.
1263	    ///
1264	    /// Instances are partitioned by device type (CPU vs non-CPU), then the router
1265	    /// applies a budget policy and selects the least-loaded instance within the
1266	    /// chosen group.
1267	    ///
1268	    /// If only one device class exists (all CPU or all non-CPU), this naturally
1269	    /// degenerates to least-loaded routing over the available instances.
1270	    pub async fn device_aware_weighted(&self, request: SingleIn<T>) -> anyhow::Result<ManyOut<U>> {
1271	        self.device_aware_weighted_prepared(request, |_, _| Ok(()))
1272	            .await
1273	            .map(|(_, stream)| stream)
1274	    }
1275	
1276	    async fn device_aware_weighted_prepared<M, F>(
1277	        &self,
1278	        request: SingleIn<T>,
1279	        prepare: F,
1280	    ) -> anyhow::Result<(M, ManyOut<U>)>
1281	    where
1282	        F: FnOnce(&mut T, u64) -> anyhow::Result<M>,
1283	    {
1284	        let state = self.occupancy_state()?;
1285	        let routing_instances = self.client.routing_instances();
1286	        let instance_ids = routing_instances.free_ids();
1287	
1288	        if instance_ids.is_empty() {
1289	            return Err(self.empty_free_pool_error(&routing_instances));
1290	        }
1291	
1292	        // Apply a unified policy for all endpoints.
1293	        let endpoint_id = self.client.endpoint.id();
1294	
1295	        let selection = self.device_aware_candidates(request.content(), instance_ids);
1296	
1297	        // Only full cache hits bypass weighted accounting; partial hits still follow the
1298	        // device-aware ratio because some image encoding remains for this request.
1299	        let (decision, counter) = state
1300	            .select_and_admit(
1301	                self.picker()?,
1302	                CandidateView::DeviceAware(&selection.candidates),
1303	                selection.context,
1304	            )
1305	            .ok_or_else(|| self.empty_free_pool_error(&routing_instances))?;
1306	        let instance_id = decision.target.worker_id;
1307	        let permit = counter
1308	            .map(|counter| OccupancyPermit::from_counter(state.clone(), instance_id, counter));
1309	        let is_cpu = selection.candidates.iter().any(|candidate| {
1310	            candidate.target.worker_id == instance_id && candidate.device == RouteDevice::Cpu
1311	        });
1312	        tracing::info!(
1313	            router_mode = "device-aware-weighted",
1314	            worker_id = instance_id,
1315	            candidate_count = selection.candidates.len(),
1316	            load = state.load(instance_id),
1317	            endpoint = %endpoint_id,
1318	            is_cpu,
1319	            embedding_cache_hit = selection.embedding_cache_hit,
1320	            request_cache_keys = selection.request_cache_keys,
1321	            "Selected worker"
1322	        );
1323	
1324	        self.dispatch_selected(instance_id, request, permit, prepare)
1325	            .await
1326	    }
1327	
1328	    fn device_aware_candidates(&self, request: &T, instance_ids: &[u64]) -> DeviceAwareCandidates {
1329	        let device_type_map = self
1330	            .client
1331	            .instances()
1332	            .iter()
1333	            .map(|instance| {
1334	                let device = if matches!(instance.device_type, Some(DeviceType::Cpu)) {
1335	                    RouteDevice::Cpu
1336	                } else {
1337	                    RouteDevice::Accelerator
1338	                };
1339	                (instance.instance_id, device)
1340	            })
1341	            .collect::<HashMap<_, _>>();
1342	        let cuda_to_cpu_ratio = std::env::var("DYN_ENCODER_CUDA_TO_CPU_RATIO")
1343	            .ok()
1344	            .and_then(|value| value.parse::<usize>().ok())
1345	            .filter(|value| *value >= 1)
1346	            .unwrap_or(8);
1347	
1348	        let (request_cache_keys, cache_matched_candidates) =
1349	            if let (Some(indexer), Some(extractor)) = (
1350	                self.multimodal_cache_indexer.as_ref(),
1351	                self.multimodal_cache_key_extractor.as_ref(),
1352	            ) {
1353	                let request_cache_keys = extractor(request);
1354	                let matched = if request_cache_keys.is_empty() {
1355	                    Vec::new()
1356	                } else {
1357	                    let mut matched = indexer.workers_with_cache_key_hits(&request_cache_keys);
1358	                    matched.retain(|(id, _)| instance_ids.contains(id));
1359	                    matched
1360	                };
1361	                (request_cache_keys, matched)
1362	            } else {
1363	                (Vec::new(), Vec::new())
1364	            };
1365	
1366	        let embedding_cache_hit = !cache_matched_candidates.is_empty();
1367	        let cache_hits = cache_matched_candidates
1368	            .into_iter()
1369	            .collect::<HashMap<_, _>>();
1370	        let request_cache_key_count = request_cache_keys
1371	            .iter()
1372	            .collect::<std::collections::HashSet<_>>()
1373	            .len();
1374	        let candidates = instance_ids
1375	            .iter()
1376	            .map(|worker_id| RouteCandidate {
1377	                target: RouteTarget::worker(*worker_id),
1378	                device: device_type_map.get(worker_id).copied().unwrap_or_default(),
1379	                cache_hits: cache_hits.get(worker_id).copied().unwrap_or_default(),
1380	            })
1381	            .collect::<Vec<_>>();
1382	
1383	        DeviceAwareCandidates {
1384	            candidates,
1385	            context: RouteContext {
1386	                required_cache_hits: request_cache_key_count,
1387	                non_cpu_to_cpu_ratio: cuda_to_cpu_ratio,
1388	            },
1389	            embedding_cache_hit,
1390	            request_cache_keys: request_cache_keys.len(),
1391	        }
1392	    }
