1437	    /// Select the next worker according to the routing mode.
1438	    /// Increments round-robin counter if applicable.
1439	    /// Returns None for modes that require request lifecycle tracking or explicit routing hints.
1440	    pub fn select_next_worker(&self) -> Option<u64> {
1441	        let routing_instances = self.client.routing_instances();
1442	        match self.router_mode {
1443	            RouterMode::RoundRobin | RouterMode::Random => self
1444	                .picker
1445	                .as_deref()?
1446	                .select(
1447	                    CandidateView::Workers(routing_instances.free_ids()),
1448	                    RouteContext::default(),
1449	                    |_| 0,
1450	                )
1451	                .map(|decision| decision.target.worker_id),
1452	            RouterMode::PowerOfTwoChoices
1453	            | RouterMode::Direct
1454	            | RouterMode::LeastLoaded
1455	            | RouterMode::DeviceAwareWeighted => None,
1456	            RouterMode::KV => {
1457	                panic!(
1458	                    "select_next_worker should not be called for {:?} routing mode",
1459	                    self.router_mode
1460	                )
1461	            }
1462	        }
1463	    }
1464	
1465	    /// Peek the next worker according to the routing mode without incrementing the counter.
1466	    /// Useful for checking if a worker is suitable before committing to it.
1467	    ///
1468	    /// `None` for [`RouterMode::Direct`] (caller-supplied routing); panics for
1469	    /// [`RouterMode::KV`], which selects via `kv_chooser::find_best_match`.
1470	    pub fn peek_next_worker(&self) -> Option<u64> {
1471	        // Select among free (admission-eligible) workers — see select_next_worker
1472	        // for the per-mode selection rationale.
1473	        let routing_instances = self.client.routing_instances();
1474	        let instance_ids = routing_instances.free_ids();
1475	        if instance_ids.is_empty() {
1476	            return None;
1477	        }
1478	
1479	        match self.router_mode {
1480	            RouterMode::RoundRobin | RouterMode::Random => self
1481	                .picker
1482	                .as_deref()?
1483	                .peek(
1484	                    CandidateView::Workers(instance_ids),
1485	                    RouteContext::default(),
1486	                    |_| 0,
1487	                )
1488	                .map(|decision| decision.target.worker_id),
1489	            RouterMode::LeastLoaded | RouterMode::PowerOfTwoChoices => self
1490	                .occupancy_state
1491	                .as_deref()?
1492	                .peek(
1493	                    self.picker.as_deref()?,
1494	                    CandidateView::Workers(instance_ids),
1495	                    RouteContext::default(),
1496	                )
1497	                .map(|decision| decision.target.worker_id),
1498	            RouterMode::DeviceAwareWeighted => {
1499	                let state = self.occupancy_state.as_deref()?;
1500	                let device_type_map: HashMap<u64, Option<DeviceType>> = self
1501	                    .client
1502	                    .instances()
1503	                    .iter()
1504	                    .map(|instance| (instance.instance_id, instance.device_type.clone()))
1505	                    .collect();
1506	                let cuda_to_cpu_ratio = std::env::var("DYN_ENCODER_CUDA_TO_CPU_RATIO")
1507	                    .ok()
1508	                    .and_then(|value| value.parse::<usize>().ok())
1509	                    .filter(|value| *value >= 1)
1510	                    .unwrap_or(8);
1511	                let candidates = instance_ids
1512	                    .iter()
1513	                    .map(|worker_id| RouteCandidate {
1514	                        target: RouteTarget::worker(*worker_id),
1515	                        device: if matches!(
1516	                            device_type_map.get(worker_id),
1517	                            Some(Some(DeviceType::Cpu))
1518	                        ) {
1519	                            RouteDevice::Cpu
1520	                        } else {
1521	                            RouteDevice::Accelerator
1522	                        },
1523	                        cache_hits: 0,
1524	                    })
1525	                    .collect::<Vec<_>>();
1526	                state
1527	                    .peek(
1528	                        self.picker.as_deref()?,
1529	                        CandidateView::DeviceAware(&candidates),
1530	                        RouteContext {
1531	                            required_cache_hits: 0,
1532	                            non_cpu_to_cpu_ratio: cuda_to_cpu_ratio,
1533	                        },
1534	                    )
1535	                    .map(|decision| decision.target.worker_id)
1536	            }
1537	            RouterMode::Direct => None,
1538	            RouterMode::KV => {
1539	                panic!(
1540	                    "peek_next_worker should not be called for {:?} routing mode",
1541	                    self.router_mode
1542	                )
1543	            }
1544	        }
1545	    }
