1556	    async fn select_exact_target(
1557	        &self,
1558	        request: &T,
1559	        pinned_worker: Option<u64>,
1560	    ) -> anyhow::Result<(u64, Option<OccupancyPermit>)> {
1561	        if let Some(instance_id) = pinned_worker {
1562	            let routing_instances = self.client.routing_instances();
1563	            if !routing_instances.routable_ids().contains(&instance_id) {
1564	                return Err(anyhow::anyhow!(
1565	                    "instance_id={instance_id} not found for endpoint {}",
1566	                    self.client.endpoint.id()
1567	                ));
1568	            }
1569	            let permit = match self.router_mode {
1570	                RouterMode::LeastLoaded
1571	                | RouterMode::PowerOfTwoChoices
1572	                | RouterMode::DeviceAwareWeighted => {
1573	                    let state = self.occupancy_state()?;
1574	                    Some(OccupancyPermit::acquire(state, instance_id))
1575	                }
1576	                RouterMode::RoundRobin
1577	                | RouterMode::Random
1578	                | RouterMode::Direct
1579	                | RouterMode::KV => None,
1580	            };
1581	            return Ok((instance_id, permit));
1582	        }
1583	
1584	        match self.router_mode {
1585	            RouterMode::LeastLoaded
1586	            | RouterMode::PowerOfTwoChoices
1587	            | RouterMode::DeviceAwareWeighted => {
1588	                let state = self.occupancy_state()?;
1589	                let routing_instances = self.client.routing_instances();
1590	                let instance_ids = routing_instances.free_ids();
1591	                if instance_ids.is_empty() {
1592	                    return Err(self.empty_free_pool_error(&routing_instances));
1593	                }
1594	
1595	                let (decision, counter) = match self.router_mode {
1596	                    RouterMode::LeastLoaded | RouterMode::PowerOfTwoChoices => state
1597	                        .select_and_admit(
1598	                            self.picker()?,
1599	                            CandidateView::Workers(instance_ids),
1600	                            RouteContext::default(),
1601	                        )
1602	                        .ok_or_else(|| self.empty_free_pool_error(&routing_instances))?,
1603	                    RouterMode::DeviceAwareWeighted => {
1604	                        let selection = self.device_aware_candidates(request, instance_ids);
1605	                        state
1606	                            .select_and_admit(
1607	                                self.picker()?,
1608	                                CandidateView::DeviceAware(&selection.candidates),
1609	                                selection.context,
1610	                            )
1611	                            .ok_or_else(|| self.empty_free_pool_error(&routing_instances))?
1612	                    }
1613	                    _ => unreachable!(),
1614	                };
1615	                let instance_id = decision.target.worker_id;
1616	                let permit = counter
1617	                    .map(|counter| OccupancyPermit::from_counter(state, instance_id, counter));
1618	                Ok((instance_id, permit))
1619	            }
1620	            RouterMode::RoundRobin => self
1621	                .select_untracked_worker(self.round_robin_picker.as_ref())
1622	                .map(|(instance_id, _)| (instance_id, None)),
1623	            RouterMode::Random => self
1624	                .select_untracked_worker(self.random_picker.as_ref())
1625	                .map(|(instance_id, _)| (instance_id, None)),
1626	            RouterMode::Direct => Err(anyhow::anyhow!(
1627	                "Worker ID required for exact dispatch in Direct routing mode"
1628	            )),
1629	            RouterMode::KV => Err(anyhow::anyhow!(
1630	                "select_and_dispatch_exact cannot select workers in KV routing mode"
1631	            )),
1632	        }
1633	    }
