1707	    async fn generate_with_fault_detection_prepared_inner<M, F>(
1708	        &self,
1709	        instance_id: u64,
1710	        mut request: SingleIn<T>,
1711	        fallback: TransportFallback<'_>,
1712	        overload_check: OverloadCheck,
1713	        prepare: F,
1714	    ) -> anyhow::Result<(M, ManyOut<U>)>
1715	    where
1716	        F: FnOnce(&mut T, u64) -> anyhow::Result<M>,
1717	    {
1718	        let route_start = Instant::now();
1719	        let request_id = request.id().to_string();
1720	        let route_span = if matches!(self.router_mode, RouterMode::KV) {
1721	            tracing::Span::none()
1722	        } else {
1723	            tracing::info_span!(
1724	                "router.route_request",
1725	                request_id = %request_id,
1726	                worker_id = instance_id,
1727	                router_mode = ?self.router_mode,
1728	            )
1729	        };
1730	
1731	        let (instance_id, address, transport_kind, instance) =
1732	            self.resolve_transport(instance_id, fallback)?;
1733	        if matches!(overload_check, OverloadCheck::Required) {
1734	            self.check_workers_available(instance_id, &request_id)?;
1735	        }
1736	
1737	        let metadata = prepare(&mut request, instance_id)?;
1738	        let request = request.map(|req| AddressedRequest::with_instance(req, address, instance));
1739	
1740	        STAGE_DURATION_SECONDS
1741	            .with_label_values(&[STAGE_ROUTE])
1742	            .observe(route_start.elapsed().as_secs_f64());
1743	
1744	        let _nvtx_transport = dynamo_nvtx_range!(transport_kind);
1745	        let stream = self
1746	            .addressed
1747	            .generate(request)
1748	            .instrument(route_span)
1749	            .await;
1750	        let stream = self.wrap_with_fault_detection(stream, instance_id)?;
1751	        Ok((metadata, stream))
1752	    }
