1754	    /// Reject early if the selected worker is overloaded and fault detection
1755	    /// is enabled. The request_id is only used for the debug-level "checked
1756	    /// worker overload state" trace; pass an empty string from callers that
1757	    /// don't have one handy.
1758	    fn check_workers_available(&self, instance_id: u64, request_id: &str) -> anyhow::Result<()> {
1759	        if !self.fault_detection_enabled {
1760	            return Ok(());
1761	        }
1762	        let routing_instances = self.client.routing_instances();
1763	        let selected_worker_overloaded = routing_instances.is_overloaded(instance_id);
1764	        let counts = routing_instances.counts();
1765	        if tracing::enabled!(tracing::Level::DEBUG) {
1766	            tracing::debug!(
1767	                request_id,
1768	                instance_id,
1769	                router_mode = ?self.router_mode,
1770	                free_workers = counts.free,
1771	                overloaded_workers = counts.overloaded,
1772	                total_workers = counts.discovered,
1773	                selected_worker_overloaded,
1774	                "checked worker overload state"
1775	            );
1776	        }
1777	        if !selected_worker_overloaded {
1778	            return Ok(());
1779	        }
1780	        tracing::warn!(
1781	            instance_id,
1782	            overloaded_workers = counts.overloaded,
1783	            total_workers = counts.discovered,
1784	            "Rejecting request: selected worker is overloaded"
1785	        );
1786	        let cause = PipelineError::ServiceOverloaded(
1787	            "Selected worker is overloaded, please retry later".into(),
1788	        );
1789	        Err(DynamoError::builder()
1790	            .error_type(ErrorType::WorkerOverloaded)
1791	            .message("Selected worker is overloaded, please retry later")
1792	            .cause(cause)
1793	            .build()
1794	            .into())
1795	    }
