1797	    /// Resolve `(instance_id, address, transport_kind_label, Instance)` for
1798	    /// the selected worker. If that worker has disappeared, apply the caller's
1799	    /// fallback policy. `CannotConnect` is returned when fallback is forbidden
1800	    /// or when a selected fallback disappears before its transport can be
1801	    /// resolved.
1802	    fn resolve_transport(
1803	        &self,
1804	        instance_id: u64,
1805	        fallback: TransportFallback<'_>,
1806	    ) -> anyhow::Result<(u64, String, &'static str, Instance)> {
1807	        use crate::component::TransportType;
1808	
1809	        let lookup = |id: u64| {
1810	            self.client
1811	                .instances()
1812	                .iter()
1813	                .find(|i| i.instance_id == id)
1814	                .map(|instance| {
1815	                    let (addr, kind) = match &instance.transport {
1816	                        TransportType::Tcp(tcp_endpoint) => {
1817	                            (tcp_endpoint.clone(), "transport.tcp.request")
1818	                        }
1819	                        TransportType::Nats(subject) => (subject.clone(), "transport.nats.request"),
1820	                    };
1821	                    (addr, kind, instance.clone())
1822	                })
1823	        };
1824	
1825	        if let Some((addr, kind, inst)) = lookup(instance_id) {
1826	            return Ok((instance_id, addr, kind, inst));
1827	        }
1828	        let allowed_fallback = match fallback {
1829	            TransportFallback::Allow => None,
1830	            TransportFallback::Deny => {
1831	                return Err(DynamoError::builder()
1832	                    .error_type(ErrorType::CannotConnect)
1833	                    .message(format!(
1834	                        "instance_id={instance_id} not found for endpoint {}",
1835	                        self.client.endpoint.id()
1836	                    ))
1837	                    .build()
1838	                    .into());
1839	            }
1840	            TransportFallback::Within(allowed) => Some(allowed),
1841	        };
1842	
1843	        let routing_instances = self.client.routing_instances();
1844	        let fallback_id = routing_instances.free_ids().iter().copied().find(|&id| {
1845	            id != instance_id && allowed_fallback.is_none_or(|allowed| allowed.contains(&id))
1846	        });
1847	        match fallback_id {
1848	            Some(id) => {
1849	                tracing::warn!(
1850	                    original_instance = instance_id,
1851	                    fallback_instance = id,
1852	                    "Instance disappeared during routing, reselecting"
1853	                );
1854	                let (addr, kind, inst) = lookup(id).ok_or_else(|| {
1855	                    DynamoError::builder()
1856	                        .error_type(ErrorType::CannotConnect)
1857	                        .message(format!(
1858	                            "Fallback instance {} also not found for endpoint {}",
1859	                            id,
1860	                            self.client.endpoint.id()
1861	                        ))
1862	                        .build()
1863	                })?;
1864	                Ok((id, addr, kind, inst))
1865	            }
1866	            // TODO(https://github.com/ai-dynamo/dynamo/issues/12383): Distinguish
1867	            // no discoverable fallback from pool-wide overload and return the
1868	            // appropriate typed error for each case.
1869	            None => Err(anyhow::anyhow!(
1870	                "Instance {} not found and no other instances available for endpoint {}",
1871	                instance_id,
1872	                self.client.endpoint.id()
1873	            )),
1874	        }
1875	    }
1876	
1877	    /// Wrap a dispatched stream with fault detection + inactivity timeout.
1878	    /// `is_inhibited` errors trigger `report_instance_down`; the timeout
1879	    /// (driven by `DYN_HTTP_BACKEND_STREAM_TIMEOUT_SECS`) yields a synthetic
1880	    /// `ResponseTimeout` and quarantines the worker.
1881	    fn wrap_with_fault_detection(
1882	        &self,
1883	        stream: anyhow::Result<ManyOut<U>>,
1884	        instance_id: u64,
1885	    ) -> anyhow::Result<ManyOut<U>> {
1886	        let stream = match stream {
1887	            Ok(stream) => stream,
1888	            Err(err) => {
1889	                if self.fault_detection_enabled {
1890	                    if is_inhibited(err.as_ref()) {
1891	                        tracing::debug!(
1892	                            "Reporting instance {instance_id} down due to error: {err}"
1893	                        );
1894	                        self.client.report_instance_down(instance_id);
1895	                    } else if match_error_chain(err.as_ref(), &[ErrorType::WorkerOverloaded], &[]) {
1896	                        // Backpressure: worker said "my queue is full,
1897	                        // retry later". Mark overloaded so this FE skips it on
1898	                        // the next selection; the next ActiveLoad event from the
1899	                        // worker monitor overwrites the overloaded set from fresh
1900	                        // metrics. This is NOT report_instance_down (fault path).
1901	                        tracing::debug!(
1902	                            "Marking instance {instance_id} overloaded due to backpressure: {err}"
1903	                        );
1904	                        self.client.mark_overloaded_immediate(instance_id);
1905	                    }
1906	                }
1907	                return Err(err);
1908	            }
1909	        };
1910	
1911	        if !self.fault_detection_enabled {
1912	            return Ok(stream);
1913	        }
1914	
1915	        let engine_ctx = stream.context();
1916	        let client = self.client.clone();
1917	        let client_for_timeout = self.client.clone();
1918	        let stream = stream.map(move |res| {
1919	            if let Some(err) = res.err()
1920	                && is_inhibited(&err)
1921	            {
1922	                tracing::debug!(
1923	                    "Reporting instance {instance_id} down due to migratable error: {err}"
1924	                );
1925	                client.report_instance_down(instance_id);
1926	            }
1927	            res
1928	        });
1929	
1930	        let stream: Pin<Box<dyn Stream<Item = U> + Send>> =
1931	            if let Some(timeout) = self.response_timeout {
1932	                Box::pin(async_stream::stream! {
1933	                    let mut inner = Box::pin(stream);
1934	                    loop {
1935	                        tokio::select! {
1936	                            biased;
1937	                            item = inner.next() => {
1938	                                match item {
1939	                                    Some(item) => yield item,
1940	                                    None => break,
1941	                                }
1942	                            }
1943	                            _ = tokio::time::sleep(timeout) => {
1944	                                tracing::warn!(
1945	                                    instance_id,
1946	                                    timeout_secs = timeout.as_secs(),
1947	                                    "backend response inactivity timeout — quarantining worker"
1948	                                );
1949	                                client_for_timeout.report_instance_down(instance_id);
1950	                                yield U::from_err(
1951	                                    crate::error::DynamoError::builder()
1952	                                        .error_type(crate::error::ErrorType::ResponseTimeout)
1953	                                        .message("backend response inactivity timeout")
1954	                                        .build()
1955	                                );
1956	                                break;
1957	                            }
1958	                        }
1959	                    }
1960	                })
1961	            } else {
1962	                Box::pin(stream)
1963	            };
1964	
1965	        Ok(ResponseStream::new(stream, engine_ctx))
1966	    }
1967	}
