1995	where
1996	    T: Data + Serialize,
1997	    U: Data + for<'de> Deserialize<'de> + MaybeError,
1998	{
1999	    /// Bidirectional sibling of [`Self::generate_with_fault_detection`].
2000	    async fn bidirectional_dispatch(
2001	        &self,
2002	        instance_id: u64,
2003	        input: ManyIn<T>,
2004	    ) -> anyhow::Result<ManyOut<U>> {
2005	        let route_start = Instant::now();
2006	        let request_id = input.context().id().to_string();
2007	        let route_span = tracing::info_span!(
2008	            "router.route_request_bidirectional",
2009	            request_id = %request_id,
2010	            worker_id = instance_id,
2011	            router_mode = ?self.router_mode,
2012	        );
2013	
2014	        let (instance_id, address, transport_kind, instance) =
2015	            self.resolve_transport(instance_id, TransportFallback::Allow)?;
2016	        self.check_workers_available(instance_id, &request_id)?;
2017	
2018	        STAGE_DURATION_SECONDS
2019	            .with_label_values(&[STAGE_ROUTE])
2020	            .observe(route_start.elapsed().as_secs_f64());
2021	
2022	        let _nvtx_transport = dynamo_nvtx_range!(transport_kind);
2023	        let stream: anyhow::Result<ManyOut<U>> = self
2024	            .addressed
2025	            .generate_bidirectional(instance, address, input)
2026	            .instrument(route_span)
2027	            .await;
2028	        self.wrap_with_fault_detection(stream, instance_id)
2029	    }
