2032	/// Bidirectional `AsyncEngine` impl for streaming-input workloads (e.g. the
2033	/// OpenAI Realtime API). Reserves a sticky worker up front — before any
2034	/// inbound frame is observed — and binds the whole input stream to that
2035	/// worker. KV and Direct modes inherit the same `bail!` invariants as the
2036	/// unary impl.
2037	///
2038	/// **Reserve-before-observe rationale.** The router-mode strategies
2039	/// (`RoundRobin`, `Random`, `PowerOfTwoChoices`, `LeastLoaded`,
2040	/// `DeviceAwareWeighted`) don't depend on frame contents, so selection
2041	/// runs immediately and connection setup proceeds in parallel with the
2042	/// client producing its first frame. A client that connects but never
2043	/// sends one still releases the slot via the response-stream-drop path;
2044	/// the dispatch-side `cancel_both` cleanup covers the early-bail case.
2045	#[async_trait]
2046	impl<T, U> AsyncEngine<ManyIn<T>, ManyOut<U>, Error> for PushRouter<T, U>
2047	where
2048	    T: Data + Serialize,
2049	    U: Data + for<'de> Deserialize<'de> + MaybeError,
2050	{
2051	    async fn generate(&self, input: ManyIn<T>) -> Result<ManyOut<U>, Error> {
2052	        match self.router_mode {
2053	            RouterMode::KV => {
2054	                anyhow::bail!("KV routing should not call generate on PushRouter");
2055	            }
2056	            RouterMode::Direct => {
2057	                anyhow::bail!(
2058	                    "Direct routing should not call generate on PushRouter directly; use RoutingHost"
2059	                );
2060	            }
2061	            // These modes drive `select_next_worker()` to `None` — they rely on
2062	            // the occupancy/load-aware selection the bidirectional path does not
2063	            // wire yet, which would otherwise surface as a misleading "no
2064	            // instances available" error below. Reject them explicitly until
2065	            // bidirectional support lands; tracked in
2066	            // https://github.com/ai-dynamo/dynamo/issues/10320.
2067	            RouterMode::PowerOfTwoChoices
2068	            | RouterMode::LeastLoaded
2069	            | RouterMode::DeviceAwareWeighted => {
2070	                anyhow::bail!(
2071	                    "{:?} routing is not yet supported for bidirectional dispatch",
2072	                    self.router_mode
2073	                );
2074	            }
2075	            RouterMode::RoundRobin | RouterMode::Random => {}
2076	        }
2077	
2078	        let instance_id = self
2079	            .select_next_worker()
2080	            .ok_or_else(|| anyhow::anyhow!("no instances available for bidirectional routing"))?;
2081	
2082	        self.bidirectional_dispatch(instance_id, input).await
2083	    }
2084	}
